import {runLinkageEvaluation} from './linkage-lab-core.mjs';
import {validateSemanticRun,semanticEvaluation} from './semantic-run.mjs';
import {initContextReview} from './context-review-app.mjs';
const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let report=null,savedRun=null,busy=false;
initContextReview();
function calcReport(){const r=runLinkageEvaluation($('lab-split').value);if(savedRun)r.results.push(semanticEvaluation(r.split,savedRun));return r;}
const pct=value=>value===null?'Not measured':`${(value*100).toFixed(1)}%`;
const firstLabel=row=>row.ranking.length?row.candidates.find(c=>c.id===row.ranking[0].id).label:'No result';
const badge=label=>`<span class="lab-label ${label.toLowerCase()}">${esc(label)}</span>`;
function render(){
 if(!report){$('lab-results').innerHTML='<p class="lab-empty">Run comparison to see first-result errors, missed related reports and every original passage.</p>';return;}
 const [base]=report.results;
 const semantic=report.results.find(m=>m.id==='multilingual');
 const rows=base.rows.map((row,i)=>({row,methods:report.results.map(m=>({name:m.name,data:m.rows[i]}))})).filter(({methods})=>{switch($('lab-filter').value){case 'false-first':return methods.some(m=>firstLabel(m.data)==='Unrelated');case 'missed':return methods.some(m=>m.data.candidates.some(c=>c.label==='Related'&&!m.data.ranking.slice(0,3).some(s=>s.id===c.id)));case 'different':return methods.some(m=>m.data.ranking.map(r=>r.id).join('|')!==methods[0].data.ranking.map(r=>r.id).join('|'));default:return true;}});
 $('lab-results').innerHTML=`<p class="lab-partition"><strong>${esc(report.split==='evaluation'?'Evaluation partition':'Development partition')}</strong> · ${base.metrics.queries} authored queries · Suite ${esc(report.suiteVersion)}</p><div class="lab-summary">${report.results.map(m=>`<article class="lab-score"><h2>${esc(m.name)}</h2><strong class="score-value">${m.metrics.correctTop1} / ${m.metrics.queries}</strong><span class="score-label">related reports ranked first</span><div class="lab-metrics"><div><strong>${m.metrics.falseTop1}</strong><span>unrelated first results</span></div><div><strong>${pct(m.metrics.recallAt3)}</strong><span>mean recall within top 3</span></div><div><strong>${m.metrics.mrr.toFixed(3)}</strong><span>mean reciprocal rank</span></div><div><strong>${m.metrics.unrelatedTop3}</strong><span>unrelated reports in top 3</span></div></div><p class="muted">${m.metrics.unresolvedTop1} unresolved first results · ${m.metrics.noResults} empty results · ${m.metrics.unresolvedTop3} unresolved reports in top 3.</p></article>`).join('')}</div><div class="lab-decision"><strong>Similarity still needs event-context review.</strong><p>${semantic?`The retained multilingual run places a related report first in ${semantic.metrics.correctTop1}/${semantic.metrics.queries} examples, with ${semantic.metrics.falseTop1} unrelated first results. Similar events can still rank above the correct event.`:'Load the saved multilingual run to compare actual local model outputs.'} Every query has only three candidates: returning all three can produce 100% recall@3 without establishing useful selection accuracy. Inspect first-result errors and review workload. No method is promoted automatically. These authored results do not measure real threat detection or prevention.</p></div><h2>Inspect the evidence behind the scores</h2><p class="muted">Showing ${rows.length} of ${base.rows.length} examples. Summary scores always include the whole selected partition.</p>${rows.length?rows.map(({row,methods})=>`<article class="panel lab-query"><div class="lab-query-heading"><div><h3>${esc(row.category)}</h3><small>${esc(row.id)} · known by ${esc(row.asOf)} · ${row.excluded} future candidates excluded</small></div><span class="chip">FICTIONAL</span></div><p class="query-text">${esc(row.query.text)}</p><div class="lab-first">${methods.map(m=>`<div>${esc(m.name)}<strong>${m.data.ranking.length?esc(m.data.ranking[0].id):'No qualifying report'}</strong>${badge(firstLabel(m.data))}</div>`).join('')}</div><details><summary>Inspect all ${row.candidates.length} original candidates and authored labels</summary>${row.candidates.map(c=>`<div class="lab-candidate"><div class="lab-candidate-head"><strong>${esc(c.id)}</strong>${badge(c.label)}</div><p>${esc(c.text)}</p><p class="muted">Authored rationale: ${esc(c.reason)}</p><p class="muted">${methods.map(m=>{const rank=m.data.ranking.findIndex(r=>r.id===c.id);return `${esc(m.name)}: ${rank<0?'not retrieved':`rank ${rank+1} · score ${m.data.ranking[rank].score.toFixed(3)}`}`;}).join(' | ')}</p><button data-context-case="${esc(row.id)}" data-context-candidate="${esc(c.id)}">Review event context</button></div>`).join('')}</details></article>`).join(''):'<p class="lab-empty">No examples match this inspection filter. The full-partition scores above are unchanged.</p>'}`;
}
$('lab-form').addEventListener('submit',event=>{event.preventDefault();try{report=calcReport();$('lab-error').textContent='';$('lab-status').textContent=`Completed ${report.split} comparison locally. No reports or workspace records changed.`;render();}catch(error){report=null;render();$('lab-error').textContent=error.message;}});
$('lab-split').addEventListener('change',()=>{report=null;render();$('lab-status').textContent='Partition changed. Run comparison to calculate its results.';$('lab-error').textContent='';});
$('lab-filter').addEventListener('change',render);render();

$('load-semantic').addEventListener('click',async()=>{if(busy)return;busy=true;$('load-semantic').disabled=true;$('lab-split').disabled=true;$('lab-form').querySelector('button').disabled=true;$('semantic-status').textContent='Loading and validating the retained synthetic model run…';try{const response=await fetch('./semantic-run.json',{credentials:'same-origin'});if(!response.ok)throw Error('The retained model run is unavailable.');const bytes=await response.text();if(bytes.length>100000)throw Error('Retained model run exceeds the expected size.');savedRun=await validateSemanticRun(JSON.parse(bytes));report=calcReport();render();$('lab-status').textContent=`Completed ${report.split} comparison locally. No reports or workspace records changed.`;$('semantic-status').textContent=`Saved local CPU inference: ${savedRun.executedAt}. Pinned MiniLM revision ${savedRun.model.revision.slice(0,12)} · ${savedRun.sources.length} source bindings · ${savedRun.model.dimensions} dimensions · no truncated reports. Loading this file does not run inference in your browser. Hash checks identify changed inputs; this editable file is not an authenticated execution receipt.`;}catch(error){savedRun=null;if(report){report=calcReport();render();}$('semantic-status').textContent=error.message;}finally{busy=false;$('load-semantic').disabled=false;$('lab-split').disabled=false;$('lab-form').querySelector('button').disabled=false;}});
